      e: L('Шеңбер ұзындығы: 2 · ' + fr(22, 7) + ' · ' + rad + ' = ' + F(C) + ' см. Жол: ' + F(D) + ' м = ' + F(D * 100) + ' см. Айналым саны: ' + F(D * 100) + ' : ' + F(C) + ' = ' + N + '. Жауабы: ' + N + '.',
           'Длина окружности: 2 · ' + fr(22, 7) + ' · ' + rad + ' = ' + F(C) + ' см. Путь: ' + F(D) + ' м = ' + F(D * 100) + ' см. Число оборотов: ' + F(D * 100) + ' : ' + F(C) + ' = ' + N + '. Ответ: ' + N + '.')
