      a: F(R),
      w: [[F(C), L('Бұл — тауықтар саны.', 'Это число кур.')],
          [F(Lg / 4), L('Барлық аяқты 4-ке бөлген, яғни барлығын қоян деп есептеген.', 'Разделили все ноги на 4, то есть посчитали всех кроликами.')],
          [F(Lg - 2 * H), L('«Артық» аяқтар санын тапқан, бірақ оны 2-ге бөлмеген: әр қоянның 2 артық аяғы бар.', 'Нашли «лишние» ноги, но не разделили на 2: у каждого кролика их 2.')]],
