      e: L('Көбейту ережесі: ' + s + ' · ' + p + ' · ' + k + ' = ' + (s * p * k) + '. Жауабы: ' + (s * p * k) + '.', 'Правило умножения: ' + s + ' · ' + p + ' · ' + k + ' = ' + (s * p * k) + '. Ответ: ' + (s * p * k) + '.')
