      e: L('Әр оқушы ' + (n - 1) + ' ойын ойнайды: ' + n + ' · ' + (n - 1) + ' = ' + (n * (n - 1)) + '. Әр ойын екі рет саналды, сондықтан ' + (n * (n - 1)) + ' : 2 = ' + ans + '. Жауабы: ' + ans + '.', 'Каждый играет ' + (n - 1) + ' партий: ' + n + ' · ' + (n - 1) + ' = ' + (n * (n - 1)) + '. Каждая партия посчитана дважды: ' + (n * (n - 1)) + ' : 2 = ' + ans + '. Ответ: ' + ans + '.')
